# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::EntryReader do
  it "reads the prepared entries table when the monolith store is prepared and timesheet_entries when it is legacy" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    projected = create(:timesheet_entry, user:, project:, work_date: Date.new(2026, 3, 2), note: "from projection")
    prepared_id = projected.id + 1000
    ActiveRecord::Base.connection.execute(<<~SQL)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, note, bill_status,
                           review_status, source, source_metadata, proof_metadata, created_at, updated_at)
      VALUES (#{prepared_id}, #{company.id}, 1, #{project.id}, #{user.id}, '2026-03-03', 60.0, 'from prepared',
              'unbilled', 'not_required', 'manual', '{}', '{}', NOW(), NOW())
    SQL
    # The monolith owns the data in both states, so Timekeeping must never be asked.
    timekeeping_client = Object.new
    def timekeeping_client.list_entries(**)
      raise "Timekeeping must not be read while the monolith owns entries"
    end

    read = lambda do
      described_class.list(company_id: company.id, user_id: user.id, from: Date.new(2026, 3, 1),
                           to: Date.new(2026, 3, 31), ownership: TimekeepingOwnership.current, timekeeping_client:)
    end

    # "The entry list and read-after-write reads go to the current owner: Timekeeping, or the prepared
    # monolith's local tables, or `timesheet_entries` in the legacy state."
    expect(read.call.map(&:note)).to eq(["from projection"])

    TimekeepingOwnership.current.update!(generation: 3, monolith_store: "prepared")
    prepared = read.call
    expect(prepared.map(&:id)).to eq([prepared_id])
    expect(prepared.first.snippet).to include(id: prepared_id, note: "from prepared", project: project.name)
    expect(prepared.first).to be_readonly
  end
end
